-- OTOTR Finance migration promoted from a reviewed candidate.
-- Source: candidate-contract-version-submit-rpc.sql
-- Source SHA256: 28664BA2B796D6895E08011C450CD1EBAA01CF326E3F7F2F8FB1CA1658D7B337
-- Local replay required before any staging promotion.
-- OTOTR CONTRACT VERSION SUBMIT RPC CANDIDATE
create or replace function finance_private.current_contract_version_submit_committer_is_trusted() returns boolean language sql stable security definer set search_path='' as $$select false$$;
create or replace function finance_private.resolve_contract_version_submit_scope(p_actor_id uuid,p_contract_version_id uuid,p_permission text) returns jsonb language sql stable security definer set search_path='' as $$select null::jsonb$$;
create or replace function finance_api.authorize_contract_version_submit(p_contract_version_id uuid,p_permission text) returns jsonb language sql stable security definer set search_path='' as $$select case when auth.uid() is null or p_permission<>'finance.contract-versions.submit' then null::jsonb else finance_private.resolve_contract_version_submit_scope(auth.uid(),p_contract_version_id,p_permission) end$$;
create or replace function finance_api.commit_contract_version_submit(p_actor_id uuid,p_legal_entity_id uuid,p_dealer_legal_entity_id uuid,p_dealer_account_id uuid,p_branch_id uuid,p_contract_version_id uuid,p_expected_version bigint,p_reason_code text,p_note_hash text,p_idempotency_key text,p_intent_hash text,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,finance,finance_private as $$
declare v record;v_existing record;v_new bigint;v_approval uuid;v_payload jsonb;v_previous text;v_audit text;
begin
 if not finance_private.current_contract_version_submit_committer_is_trusted() then raise exception using errcode='42501',message='trusted contract version submit committer required';end if;
 if p_expected_version<1 or (p_reason_code is not null and pg_catalog.length(pg_catalog.btrim(p_reason_code)) not between 1 and 100) or (p_note_hash is not null and p_note_hash!~'^[a-fA-F0-9]{64}$') or pg_catalog.length(pg_catalog.btrim(coalesce(p_idempotency_key,''))) not between 8 and 200 or p_intent_hash!~'^[a-fA-F0-9]{64}$' then raise exception using errcode='22023',message='invalid contract version submit command';end if;
 select cv.*,fc.legal_entity_id,fc.dealer_legal_entity_id,fc.status contract_status into v from finance.contract_versions cv join finance.franchise_contracts fc on fc.id=cv.contract_id where cv.id=p_contract_version_id for update of cv,fc;if not found then raise exception using errcode='P0002',message='contract version not found';end if;
 select om.payload into v_existing from finance.outbox_messages om where om.legal_entity_id=v.legal_entity_id and om.event_type='CONTRACT_VERSION_SUBMITTED' and om.aggregate_id=v.id and om.payload->>'idempotencyKey'=p_idempotency_key order by om.created_at_utc desc,om.id desc limit 1;if found then if v_existing.payload->>'intentHash'=p_intent_hash then return pg_catalog.jsonb_build_object('outcome','REPLAY','versionId',v.id,'status','PENDING_APPROVAL','version',(v_existing.payload->>'version')::bigint,'approvalRequestId',v_existing.payload->>'approvalRequestId');end if;return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if v.legal_entity_id<>p_legal_entity_id or v.dealer_legal_entity_id<>p_dealer_legal_entity_id or v.contract_status in ('TERMINATED','DISCARDED') or v.status<>'DRAFT' or v.version<>p_expected_version then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if not exists(select 1 from finance.dealer_accounts da join finance.branches b on b.legal_entity_id=da.legal_entity_id and b.dealer_legal_entity_id=da.dealer_legal_entity_id where da.id=p_dealer_account_id and da.legal_entity_id=p_legal_entity_id and da.dealer_legal_entity_id=p_dealer_legal_entity_id and b.id=p_branch_id) then raise exception using errcode='42501',message='contract version submit three dimensional scope denied';end if;
 if not exists(select 1 from finance.document_links dl where dl.legal_entity_id=p_legal_entity_id and dl.subject_type='CONTRACT_VERSION' and dl.subject_id=v.id) then raise exception using errcode='23514',message='contract version evidence required';end if;
 if not exists(select 1 from finance.contract_fee_rules r where r.contract_version_id=v.id) then raise exception using errcode='23514',message='contract version fee rule required';end if;
 if exists(select 1 from finance.contract_fee_rules r where r.contract_version_id=v.id and (r.status<>'DRAFT' or r.configuration_status<>'CONFIGURED' or r.trigger_event_type is null or r.trigger_conditions is null or pg_catalog.jsonb_typeof(r.trigger_conditions)<>'array' or r.basis_definition is null or r.calculation_method is null or r.calculation_parameters is null or r.tax_code_version_id is null or r.due_rule is null or r.cancellation_policy is null or r.price_includes_tax is null or r.currency_code is distinct from v.currency_code or r.decimal_scale is null or r.rounding_mode is null)) then raise exception using errcode='23514',message='all fee rules must be draft and completely configured';end if;
 if exists(select 1 from finance.rule_exceptions e join finance.contract_fee_rules r on r.id=e.contract_fee_rule_id where r.contract_version_id=v.id and e.status not in ('DISABLED','SUPERSEDED')) then raise exception using errcode='0A000',message='rule exception precedence decision pending';end if;
 if exists(select 1 from finance.contract_versions other where other.contract_id=v.contract_id and other.id<>v.id and other.status='ACTIVE' and v.effective_from<coalesce(other.effective_to,'infinity'::date) and other.effective_from<coalesce(v.effective_to,'infinity'::date)) then raise exception using errcode='23P01',message='contract version active date overlap';end if;
 insert into finance.approval_requests(legal_entity_id,subject_type,subject_id,approval_policy_version,prepared_by,status,version,created_by,correlation_id) values(p_legal_entity_id,'CONTRACT_VERSION',v.id,'CONTRACT_VERSION_V1',p_actor_id,'PENDING',1,p_actor_id,p_correlation_id) returning id into v_approval;
 insert into finance.approval_steps(approval_request_id,step_no,required_role,created_by,correlation_id) values(v_approval,1,'finance-approver',p_actor_id,p_correlation_id);
 update finance.contract_fee_rules set status='PENDING_APPROVAL',prepared_by=p_actor_id,version=version+1,correlation_id=p_correlation_id where contract_version_id=v.id and status='DRAFT' and configuration_status='CONFIGURED';
 v_new:=v.version+1;update finance.contract_versions set status='PENDING_APPROVAL',prepared_by=p_actor_id,version=v_new,correlation_id=p_correlation_id where id=v.id;
 v_payload:=pg_catalog.jsonb_build_object('versionId',v.id,'contractId',v.contract_id,'approvalRequestId',v_approval,'dealerLegalEntityId',v.dealer_legal_entity_id,'branchId',p_branch_id,'contentHash',v.content_hash,'version',v_new,'reasonCode',p_reason_code,'noteHash',p_note_hash,'idempotencyKey',p_idempotency_key,'intentHash',p_intent_hash);
 insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(p_legal_entity_id,'finance.contract','CONTRACT_VERSION_SUBMITTED','CONTRACT_VERSION',v.id,v_new,v_payload,p_intent_hash,'PENDING',p_correlation_id);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||p_legal_entity_id::text,0));select integrity_hash into v_previous from finance.audit_events where legal_entity_id=p_legal_entity_id order by created_at_utc desc,id desc limit 1;v_audit:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(v_previous,'GENESIS')||':'||v.id::text||':CONTRACT_VERSION_SUBMITTED:'||v.content_hash||':'||p_correlation_id::text,'UTF8'),'sha256'),'hex');insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,reason_code,before_hash,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(p_legal_entity_id,p_actor_id,'USER','CONTRACT_VERSION_SUBMITTED','CONTRACT_VERSION',v.id,'ALLOW',p_reason_code,v.content_hash,v.content_hash,v_previous,v_audit,pg_catalog.jsonb_build_object('contractId',v.contract_id,'approvalRequestId',v_approval,'branchId',p_branch_id,'noteHash',p_note_hash,'previousVersion',v.version),p_correlation_id);
 return pg_catalog.jsonb_build_object('outcome','SUBMITTED','versionId',v.id,'status','PENDING_APPROVAL','version',v_new,'approvalRequestId',v_approval);
end$$;
revoke all on function finance_private.current_contract_version_submit_committer_is_trusted() from public,anon,authenticated;revoke all on function finance_private.resolve_contract_version_submit_scope(uuid,uuid,text) from public,anon,authenticated;revoke all on function finance_api.authorize_contract_version_submit(uuid,text) from public,anon;grant execute on function finance_api.authorize_contract_version_submit(uuid,text) to authenticated;revoke all on function finance_api.commit_contract_version_submit(uuid,uuid,uuid,uuid,uuid,uuid,bigint,text,text,text,text,uuid) from public,anon,authenticated;
